L["Shards of Myzrael"] = "Shards of Myzrael"
L["the northern mountains, Arathi Highlands"] = "the northern mountains, Arathi Highlands"
L["Drywhisker Gorge, Arathi Highlands"] = "Drywhisker Gorge, Arathi Highlands"
L["Iridescent Shards"] = "Iridescent Shards"
L["the Circle of Inner Binding, Arathi Highlands"] = "the Circle of Inner Binding, Arathi Highlands"
